  base64 -d > "$TMPPLYMOUTH/lock.png" <<'B64EOF'
iVBORw0KGgoAAAANSUhEUgAAAFQAAABgCAMAAAC0XqVIAAAAIGNIUk0AAHomAACAhAAA+gAAAIDo
AAB1MAAA6mAAADqYAAAXcJy6UTwAAAFNUExURc3W9M3W9M3W9M3W9M3W9M3W9M3W9M3W9M3W9M3W
