window#waybar { background: #1e1e2e; color: #cdd6f4; padding-left: 6px; padding-right: 6px; }
window#waybar { border-radius: 8px; }
#workspaces button.focused { color: #cba6f7; border-bottom: 2px solid #cba6f7; }
