#custom-backlight { color: #1e1e2e; background: #89dceb; }
#custom-sep-sky-mauve { color: #89dceb; background: #cba6f7; font-size: 14pt; }
#pulseaudio { color: #1e1e2e; background: #cba6f7; }
#custom-sep-mauve-teal { color: #cba6f7; background: #94e2d5; font-size: 14pt; }
#custom-media { color: #1e1e2e; background: #94e2d5; }
