cat > "$CONF/waybar/themes/isabel/config.jsonc" <<'WB_EOF'
{
  "layer": "top",
  "position": "top",
  "height": 30,
  "modules-left": [
    "sway/workspaces"
  ],
  "modules-center": [],
  "modules-right": [
    "custom/backlight",
    "custom/dots",
    "pulseaudio",
    "custom/dots",
    "custom/media",
    "custom/dots",
    "custom/cliamp",
    "custom/dots",
    "network",
    "custom/network-wireless",
    "custom/dots",
    "custom/bluetooth",
    "custom/dots",
    "custom/caffeine",
    "custom/dots",
    "custom/dnd",
    "custom/dots",
    "battery",
    "custom/dots",
    "memory",
    "custom/dots",
    "cpu",
    "custom/dots",
    "custom/updates",
    "custom/dots",
    "custom/layout",
    "custom/dots",
    "tray",
    "custom/dots",
    "clock"
  ],
  "sway/workspaces": {
    "disable-scroll": true,
    "all-outputs": false,
    "format": "{name}"
  },
  "custom/backlight": {
    "exec": "~/.local/bin/polybar-backlight.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 1,
    "on-scroll-up": "brightnessctl set +5%",
    "on-scroll-down": "brightnessctl set 5%-"
  },
  "custom/dots": {
    "format": " 󰇙 ",
    "tooltip": false
  },
  "pulseaudio": {
    "format": "{volume}%",
    "format-muted": "muted",
    "tooltip": false,
    "on-click-middle": "pavucontrol"
  },
  "custom/media": {
    "exec": "~/.local/bin/polybar-media.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 1,
    "on-click": "playerctl play-pause",
    "on-click-right": "playerctl next",
    "on-click-middle": "playerctl previous"
  },
  "custom/cliamp": {
    "exec": "~/.local/bin/polybar-cliamp.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 3,
    "on-click": "~/.local/bin/cliamp-toggle.sh"
  },
  "network": {
    "format-ethernet": "{ifname}",
    "format-wifi": "{ifname}",
    "format-linked": "{ifname}",
    "format-disconnected": "",
    "tooltip": false
  },
  "custom/network-wireless": {
    "exec": "WIFI_PREFIX='' WIFI_SUFFIX='' WIFI_CONNECTED_FG='#A8C5C0' WIFI_OFF_FG='#D67F7F' ~/.local/bin/polybar-wifi.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 3,
    "on-click": "~/.local/bin/wifi-menu.sh",
    "on-click-middle": "nm-connection-editor",
    "on-click-right": "~/.local/bin/wifi-toggle.sh"
  },
  "custom/bluetooth": {
    "exec": "~/.local/bin/polybar-bluetooth.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 5,
    "on-click": "blueman-manager"
  },
  "custom/caffeine": {
    "exec": "~/.local/bin/polybar-caffeine.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 3,
    "on-click": "~/.local/bin/caffeine-toggle.sh",
    "on-click-right": "xset s activate"
  },
  "custom/dnd": {
    "exec": "~/.local/bin/polybar-dnd.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 2,
    "on-click": "~/.local/bin/dnd-toggle.sh",
    "on-click-middle": "~/.local/bin/notification-center.sh",
    "on-click-right": "dunstctl history-clear"
  },
  "battery": {
    "format": "{capacity}%",
    "format-charging": "{capacity}%",
    "format-full": "Full",
    "tooltip": false
  },
  "memory": {
    "format": "{percentage}%",
    "interval": 2,
    "tooltip": false
  },
  "cpu": {
    "format": "{usage}%",
    "interval": 2,
    "tooltip": false
  },
  "custom/updates": {
    "exec": "~/.local/bin/polybar-updates.sh",
    "format": "{}",
    "tooltip": false,
    "on-click": "kitty --class UpdatesTask -e ~/.local/bin/software-update.sh"
  },
  "custom/layout": {
    "exec": "~/.local/bin/polybar-layout.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 1
  },
  "tray": {
    "spacing": 8
  },
  "clock": {
    "format": "{:%Y-%m-%d  %H:%M}",
    "interval": 1,
    "tooltip": false,
    "on-click": "GTK_THEME=Rice-isabel gnome-calendar"
  }
}
WB_EOF
