    "exec": "WIFI_PREFIX='' WIFI_SUFFIX='' WIFI_CONNECTED_FG='#FDFDFD' WIFI_OFF_FG='#F37F97' ~/.local/bin/polybar-wifi.sh",
    "format": "{}",
    "tooltip": false,
