  },
  "custom/caffeine": {
    "exec": "~/.local/bin/polybar-caffeine.sh",
    "format": "{}",
    "tooltip": false,
    "interval": 3,
    "on-click": "~/.local/bin/caffeine-toggle.sh",
    "on-click-right": "xset s activate"
  },
