 * rofi config sets bg-selected to the exact same value as bg
 * (`bg: #1a1b2666; bg-selected: #1a1b2666;`), making the selected row
 * invisible in practice - given a real, visible highlight here instead. */
* {
    base:     #1A1B26db;
    mantle:   #1A1B2603;
    text:     #E5E9F0ff;
    subtext:  #444B61ff;
    lavender: #ACB0D0ff;
    surface0: #292A4480;

    background-color: @mantle;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 30%;
    border-radius: 0px;
    background-color: @base;
}

inputbar {
    padding: 10px;
    background-color: @mantle;
    border-radius: 0px;
    children: [prompt, entry];
}

prompt { text-color: @lavender; padding: 0 8px 0 0; }
entry  { text-color: @text; }

listview {
    lines: 14;
    padding: 8px 0;
}

element {
    padding: 6px 10px;
    border-radius: 0px;
}
element-text, element-icon {
    background-color: inherit;
    text-color: inherit;
}

element selected {
    background-color: @surface0;
    text-color: @lavender;
}
EOF
cat > "$CONF/rofi/themes/breddie-square-powermenu.rasi" <<'EOF'
* {
    base:     #1A1B26db;
    mantle:   #1A1B2603;
    text:     #E5E9F0ff;
    subtext:  #444B61ff;
    lavender: #ACB0D0ff;
    surface0: #292A4480;

    background-color: @mantle;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @lavender;
    border-radius: 0px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 0px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @lavender;
    border-radius: 0px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
EOF

