cat > "$CONF/starship/themes/sedo-dracula.toml" <<'EOF'
format = """
[](#282A36)\
$python\
$username\
[](bg:#4D4D4D fg:#282A36)\
$directory\
[](fg:#4D4D4D bg:#4D4D4D)\
$git_branch\
$git_status\
[](fg:#4D4D4D bg:#5AF78E)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#5AF78E bg:#FF79C6)\
$docker_context\
[](fg:#FF79C6 bg:#BD93F9)\
$time\
[ ](fg:#BD93F9)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#282A36"
style_root = "bg:#282A36"
format = '[$user ]($style)'

[directory]
style = "bg:#4D4D4D"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#FF79C6"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#4D4D4D"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#4D4D4D"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#282A36"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#5AF78E"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#BD93F9"
format = '[ $time ]($style)'
EOF
