cat > "$CONF/rofi/themes/sedo-everforest-powermenu.rasi" <<'EOF'
* {
    base:     #272E33ff;
    mantle:   #272E33ff;
    text:     #D3C6AAff;
    subtext:  #495156ff;
    mauve:    #7FBBB3ff;
    surface0: #495156ff;

    background-color: @base;
