cat > "$CONF/rofi/themes/sedo-gruvbox-powermenu.rasi" <<'EOF'
* {
    base:     #282828ff;
    mantle:   #282828ff;
    text:     #D4BE98ff;
    subtext:  #665C54ff;
    mauve:    #7DAEA3ff;
    surface0: #665C54ff;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 16px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @mauve;
    border-radius: 14px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
EOF
cat > "$CONF/starship/themes/sedo-gruvbox.toml" <<'EOF'
format = """
[](#282828)\
$python\
$username\
[](bg:#665C54 fg:#282828)\
$directory\
[](fg:#665C54 bg:#665C54)\
$git_branch\
$git_status\
[](fg:#665C54 bg:#B8BB26)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#B8BB26 bg:#D3869B)\
$docker_context\
[](fg:#D3869B bg:#7DAEA3)\
$time\
[ ](fg:#7DAEA3)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#282828"
style_root = "bg:#282828"
format = '[$user ]($style)'

[directory]
style = "bg:#665C54"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#D3869B"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#665C54"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#665C54"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#282828"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#B8BB26"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#7DAEA3"
format = '[ $time ]($style)'
EOF
