bottom = false
fixed-center = false

width = 98%
height = 22

offset-x = 1%
offset-y = 0.5%

background = ${color.bg}
foreground = ${color.fg}

radius = 

line-size = 2

border-size = 6
border-color = ${color.bg}

padding-left = 0
padding-right = 2

module-margin-left = 0
module-margin-right = 0

font-0 = "Iosevka Nerd Font:style=Bold:size=12;3"
font-1 = "Material Design Icons Desktop:size=14;3"
font-2 = "Font Awesome 6 Pro Solid:size=10;3"
font-3 = "Iosevka Nerd Font:style=Bold:size=16;3"
font-4 = "MesloLGS NF:size=13;3"
font-5 = "JetBrainsMono Nerd Font:style=Bold:size=13;3"

modules-left = distro sep2 bspwm sep2 weather
modules-center =
modules-right = mpd sep2 updates sep2 network sep2 battery sep2 date

separator = 
dim-value = 1.0
;locale = es_MX.UTF-8

tray-position = right
tray-detached = false
tray-maxsize = 16
tray-background = ${color.bg}
tray-offset-x = 0
tray-offset-y = 0
tray-padding = 0
tray-scale = 1.0

wm-restack = bspwm
enable-ipc = true

cursor-click = pointer
cursor-scroll = 

[settings]

screenchange-reload = false

compositing-background = source
compositing-foreground = over
compositing-overline = over
compositing-underline = over
compositing-border = over

pseudo-transparency = false
SEDO_EOF
cat > "$CONF/polybar/sedo/nord/modules.ini" <<'SEDO_EOF'
######################################################

[module/date]
type = internal/date

interval = 1.0

time = %A - %B%d [%H:%M]

format = <label>
; format-prefix = "  "
format-prefix-background = ${color.green}
format-prefix-foreground= ${color.bg}
label = "%date% %time% "

label-background = ${color.green}
label-foreground= ${color.bg}

######################################################

[module/network]
type = internal/network
interface = ${env:NET_INTERFACE}

interval = 3.0
accumulate-stats = true
unknown-as-up = true
speed-unit = ""

format-connected = <label-connected>
format-connected-prefix = "  "
label-connected = " %netspeed% "
format-connected-prefix-foreground = ${color.alt-fg}

label-connected-foreground = ${color.alt-fg}

format-disconnected = <label-disconnected>
format-disconnected-prefix = "  "
format-disconnected-foreground = ${color.alt-fg}

label-disconnected = "Disconnected "
label-disconnected-foreground = ${color.alt-fg}

######################################################

[module/bspwm]
type = internal/bspwm

enable-click = true
enable-scroll = true
reverse-scroll = true
pin-workspaces = true
occupied-scroll = false

ws-icon-0 = 1;1
ws-icon-1 = 2;2
ws-icon-2 = 3;3
ws-icon-3 = 4;4
ws-icon-4 = 5;5
ws-icon-5 = 6;6


format = "<label-state>"
format-font = 6

label-focused = %icon%
label-focused-padding = 1
label-focused-foreground = ${color.orange}
label-focused-background = ${color.alt-bg}
label-focused-underline = ${color.cyan}

label-occupied = %icon%
label-occupied-padding = 1
label-occupied-foreground= ${color.bg}
label-occupied-background = ${color.alt-bg}

label-urgent = %icon%
label-urgent-padding = 1

label-empty = %icon%
label-empty-foreground = ${color.fg}
label-empty-background = ${color.alt-bg}
label-empty-padding = 1

label-separator = ""
label-separator-padding = 0
label-separator-foreground = ${color.alt-bg}

[module/bspL]
type = custom/text

content = "%{T5}%{T-}"
content-foreground = ${color.alt-bg}

[module/bspR]
type = custom/text

content = "%{T5}%{T-}"
content-foreground = ${color.alt-bg}

[module/bspRR]
type = custom/text

content = "%{T5}%{T-}"
content-foreground = ${color.blue}

######################################################

[module/updates]
type = custom/script
exec = ~/.config/bspwm/scripts/Updates
interval = 120
; tail = true
label = "%{T1} %output% %{T-}"
label-foreground = ${color.alt-fg}
click-left = alacritty --class float,float -e sudo pacman -Syyu
format-prefix = "  "
format-prefix-foreground = ${color.alt-fg}

######################################################

[module/sep]
type = custom/text
content = " "
content-foreground = ${color.current}

######################################################

[module/sep2]
type = custom/text
content = "  "
content-foreground = ${color.current}

#----

[module/mpd]
type                    = internal/mpd
host                    = 127.0.0.1
port                    = 6600
interval                = 2
format-online           = "<icon-repeat>%{F#9ece6a}%{F-} %{A1:mpc toggle:}<label-song>%{A} %{F#9ece6a}%{F-}"
format-offline          = ""
label-song              = "%{T1}%title%%{T-}"
label-song-foreground   = ${color.alt-fg}
label-song-maxlen       = 38
icon-repeat             = "󰎈"

toggle-on-foreground    = ${color.alt-fg}
toggle-off-foreground   = ${color.alt-fg}

#----

[module/battery]
;https://github.com/jaagr/polybar/wiki/Module:-battery
type = internal/battery
battery = BAT0
adapter = AC0
full-at = 100

format-charging = <animation-charging><label-charging>
label-charging =   "%percentage%% "
label-charging-foreground = ${color.red}

format-discharging = <ramp-capacity><label-discharging>
label-discharging =   "%percentage%% "
label-discharging-foreground = ${color.red}

format-full-prefix = "   "
label-full =   "%percentage%% "

format-full-prefix-font = 1
format-full-prefix-foreground = ${color.red}
format-full-foreground = ${color.red}

ramp-capacity-0 = "   "
ramp-capacity-1 = "   "
ramp-capacity-2 = "   "
ramp-capacity-3 = "   "
ramp-capacity-4 = "   "
ramp-capacity-foreground = ${color.red}
ramp-capacity-font = 1

animation-charging-0 = "   "
animation-charging-1 = "   "
animation-charging-2 = "   "
animation-charging-3 = "   "
animation-charging-4 = "   "
animation-charging-font = 1
animation-charging-foreground = ${color.red}
animation-charging-framerate = 750

#----

[module/distro]
type = custom/script
exec = distro

format = <label>
label = "%{T4}%{F#dbc074}%{A1:rofi -show run:}%output%%{A}%{F-}%{T-}"

#----

[module/weather]
type = custom/script
exec = weather
interval = 120
format = <label>
label = " %output% "
label-foreground= ${color.blue}

#----
SEDO_EOF
cat > "$CONF/rofi/themes/sedo-nord.rasi" <<'EOF'
* {
    base:     #2E3440ff;
    mantle:   #2E3440ff;
    text:     #D8DEE9ff;
    subtext:  #4C566Aff;
    mauve:    #81A1C1ff;
    surface0: #4C566Aff;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 30%;
    border-radius: 12px;
    background-color: @base;
}

inputbar {
    padding: 10px;
    background-color: @mantle;
    border-radius: 8px;
    children: [prompt, entry];
}

prompt { text-color: @mauve; padding: 0 8px 0 0; }
entry  { text-color: @text; }

listview {
    lines: 14;
    padding: 8px 0;
}

element {
    padding: 6px 10px;
    border-radius: 6px;
}
element-text, element-icon {
    background-color: inherit;
    text-color: inherit;
}

element selected {
    background-color: @surface0;
    text-color: @mauve;
}
EOF
cat > "$CONF/rofi/themes/sedo-nord-powermenu.rasi" <<'EOF'
* {
    base:     #2E3440ff;
    mantle:   #2E3440ff;
    text:     #D8DEE9ff;
    subtext:  #4C566Aff;
    mauve:    #81A1C1ff;
    surface0: #4C566Aff;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 16px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @mauve;
    border-radius: 14px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
EOF
cat > "$CONF/starship/themes/sedo-nord.toml" <<'EOF'
format = """
[](#2E3440)\
$python\
$username\
