$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#B1D196 bg:#B48EAD)\
$docker_context\
[](fg:#B48EAD bg:#81A1C1)\
$time\
[ ](fg:#81A1C1)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#2E3440"
style_root = "bg:#2E3440"
format = '[$user ]($style)'

[directory]
style = "bg:#4C566A"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#B48EAD"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#4C566A"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#4C566A"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#2E3440"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#B1D196"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#81A1C1"
format = '[ $time ]($style)'
EOF
