    background-color: @surface0;
    text-color: @mauve;
}
EOF
cat > "$CONF/rofi/themes/sedo-onedark-powermenu.rasi" <<'EOF'
* {
    base:     #282C34ff;
    mantle:   #282C34ff;
    text:     #BBC2CFff;
    subtext:  #5B6268ff;
    mauve:    #51AFEFff;
    surface0: #5B6268ff;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 16px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @mauve;
    border-radius: 14px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
EOF
cat > "$CONF/starship/themes/sedo-onedark.toml" <<'EOF'
format = """
[](#282C34)\
$python\
$username\
[](bg:#5B6268 fg:#282C34)\
$directory\
[](fg:#5B6268 bg:#5B6268)\
$git_branch\
$git_status\
[](fg:#5B6268 bg:#A2CD83)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#A2CD83 bg:#C678DD)\
$docker_context\
[](fg:#C678DD bg:#51AFEF)\
$time\
[ ](fg:#51AFEF)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#282C34"
style_root = "bg:#282C34"
format = '[$user ]($style)'

[directory]
style = "bg:#5B6268"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#C678DD"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#5B6268"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#5B6268"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#282C34"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#A2CD83"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#51AFEF"
format = '[ $time ]($style)'
EOF
