cat > "$CONF/rofi/themes/gh0stzk-aline-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #FAF4EDFF;
    mantle:   #F2E9E1FF;
    text:     #575279FF;
    subtext:  #9893A5FF;
    mauve:    #D7827EFF;
    surface0: #F2E9E1FF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

