cat > "$CONF/starship/themes/gh0stzk-aline.toml" <<'GH0STZK_EOF'
format = """
[](#FAF4ED)\
$python\
$username\
[](bg:#F2E9E1 fg:#FAF4ED)\
$directory\
[](fg:#F2E9E1 bg:#F2E9E1)\
$git_branch\
$git_status\
[](fg:#F2E9E1 bg:#286983)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#286983 bg:#907AA9)\
$docker_context\
[](fg:#907AA9 bg:#56949F)\
$time\
[ ](fg:#56949F)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#FAF4ED"
style_root = "bg:#FAF4ED"
format = '[$user ]($style)'

[directory]
style = "bg:#F2E9E1"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#907AA9"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#F2E9E1"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#F2E9E1"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#FAF4ED"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#286983"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#56949F"
format = '[ $time ]($style)'
GH0STZK_EOF
