cat > "$CONF/starship/themes/gh0stzk-brenda.toml" <<'GH0STZK_EOF'
format = """
[](#2D353B)\
$python\
$username\
[](bg:#475258 fg:#2D353B)\
$directory\
[](fg:#475258 bg:#475258)\
$git_branch\
$git_status\
[](fg:#475258 bg:#A7C080)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#A7C080 bg:#D699B6)\
$docker_context\
[](fg:#D699B6 bg:#7FBBB3)\
$time\
[ ](fg:#7FBBB3)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#2D353B"
style_root = "bg:#2D353B"
format = '[$user ]($style)'

[directory]
style = "bg:#475258"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#D699B6"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#475258"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#475258"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#2D353B"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#A7C080"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#7FBBB3"
format = '[ $time ]($style)'
GH0STZK_EOF
