cat > "$CONF/rofi/themes/gh0stzk-cristina-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #232136FF;
    mantle:   #2A2740FF;
    text:     #E0DEF4FF;
    subtext:  #6E6A86FF;
    mauve:    #C3A5E6FF;
