cat > "$CONF/starship/themes/gh0stzk-cristina.toml" <<'GH0STZK_EOF'
format = """
[](#232136)\
$python\
$username\
[](bg:#393552 fg:#232136)\
$directory\
[](fg:#393552 bg:#393552)\
$git_branch\
$git_status\
[](fg:#393552 bg:#9BCED7)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#9BCED7 bg:#C3A5E6)\
$docker_context\
[](fg:#C3A5E6 bg:#34738E)\
$time\
[ ](fg:#34738E)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#232136"
style_root = "bg:#232136"
format = '[$user ]($style)'

[directory]
style = "bg:#393552"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#C3A5E6"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#393552"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#393552"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#232136"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#9BCED7"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#34738E"
format = '[ $time ]($style)'
GH0STZK_EOF
