cat > "$CONF/rofi/themes/gh0stzk-cynthia-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #181616FF;
    mantle:   #1C1A1AFF;
    text:     #C5C9C5FF;
    subtext:  #A6A69CFF;
    mauve:    #8A9A7BFF;
    surface0: #1C1A1AFF;

    background-color: @base;
