cat > "$CONF/starship/themes/gh0stzk-cynthia.toml" <<'GH0STZK_EOF'
format = """
[](#181616)\
$python\
$username\
[](bg:#0D0C0C fg:#181616)\
$directory\
[](fg:#0D0C0C bg:#0D0C0C)\
$git_branch\
$git_status\
[](fg:#0D0C0C bg:#8A9A7B)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#8A9A7B bg:#A292A3)\
$docker_context\
[](fg:#A292A3 bg:#8BA4B0)\
$time\
[ ](fg:#8BA4B0)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#181616"
style_root = "bg:#181616"
format = '[$user ]($style)'

[directory]
style = "bg:#0D0C0C"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#A292A3"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#0D0C0C"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#0D0C0C"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#181616"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#8A9A7B"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#8BA4B0"
format = '[ $time ]($style)'
GH0STZK_EOF
