[module/updates]
type = custom/ipc

hook-0 = cat $HOME/.cache/Updates.txt 2>/dev/null
initial = 1

format = <label>
format-prefix = "UPDATES"
format-prefix-font = 1
format-prefix-foreground = ${color.purple}

label = %output%
label-padding = 2pt
label-font = 5

click-left = OpenApps --checkupdates

######################################################

[module/launcher]
type = custom/text

format-prefix = "󰣇"
format-prefix-font = 4
format-prefix-foreground = ${color.green}

label = "Arch"
label-font = 1

click-left = OpenApps --menu
click-right = RiceSelector

######################################################

[module/sep]
type = custom/text
label = " "
label-foreground = ${color.bg}

######################################################

[module/cpu_bar]
type = internal/cpu

interval = 0.5

format = <label>
format-prefix = "CPU"
format-prefix-font = 1
format-prefix-foreground = ${color.blue}

label = "%percentage%%"
label-padding = 2pt
label-font = 5

######################################################

[module/memory_bar]
type = internal/memory

interval = 3

format = <label>
format-prefix = "RAM"
format-prefix-font = 1
format-prefix-foreground = ${color.yellow}

label = %used%
label-padding = 2pt
label-font = 5

######################################################

[module/mpd_control]
type            = internal/mpd
host            = 127.0.0.1
port            = 6600
interval        = 2
format-online   = <icon-prev><toggle><icon-next>
format-offline  = <label-offline>
label-offline = " No Music"
icon-play               = " %{T2}%{T-} "
icon-pause              = " %{T2}%{T-} "
icon-stop               = " %{T2}%{T-} "
icon-prev               = "%{T2}%{T-} "
icon-next               = " %{T2}%{T-}"

format-offline-foreground = ${color.grey}
icon-play-foreground    = ${color.green}
icon-pause-foreground   = ${color.green}
icon-stop-foreground    = ${color.green}
icon-prev-foreground    = ${color.blue}
icon-next-foreground    = ${color.blue}
toggle-on-foreground    = ${color.green}
toggle-off-foreground   = ${color.red}

#####################################################

[module/mplayer]
type = custom/text
label = ""
label-padding = 2pt
label-foreground = ${color.purple}

click-left = OpenApps --player
click-right = OpenApps --music

[module/usercard]
type = custom/text
label =  ""
label-padding = 2pt
label-foreground = ${color.cyan}

click-left = OpenApps --usercard

[module/power]
type = custom/text
label = ""
label-padding = 2pt
label-foreground = ${color.red}

click-left = OpenApps --powermenu

#####################################################

[module/tray]
type = internal/tray

format = <tray>
format-background = ${color.bg}
tray-background = ${color.bg}
tray-foreground = ${color.fg}
tray-spacing = 8px
tray-padding = 0px
tray-size = 40%

#####################################################

[module/bluetooth]
type = custom/script
exec = bluetooth-polybar.sh
interval = 3

format = <label>
format-font = 6
label = "%output%"
click-left = OpenApps --bluetooth

#####################################################

[module/xkeyboard]
type = internal/xkeyboard

blacklist-0 = num lock
blacklist-1 = scroll lock

format = <label-layout>
format-prefix = "KB"
format-prefix-font = 1
format-prefix-foreground = ${color.cyan}

label-layout = %{A1:OpenApps --keyboard:}%layout%%{A}
label-layout-padding = 2pt
label-layout-font = 5

#####################################################

[module/colorpicker]
type = custom/text
label = ""
label-foreground = ${color.yellow}
click-left = Colorpicker
GH0STZK_EOF
cat > "$CONF/rofi/themes/gh0stzk-daniela.rasi" <<'GH0STZK_EOF'
* {
    base:     #181825FF;
    mantle:   #1E1E2EFF;
    text:     #CDD6F4FF;
    subtext:  #585B70FF;
    mauve:    #F5C2E7FF;
    surface0: #1E1E2EFF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 30%;
    border-radius: 12px;
    background-color: @base;
}

inputbar {
    padding: 10px;
    background-color: @mantle;
    border-radius: 8px;
    children: [prompt, entry];
}

prompt { text-color: @mauve; padding: 0 8px 0 0; }
entry  { text-color: @text; }

listview {
    lines: 14;
    padding: 8px 0;
}

element {
    padding: 6px 10px;
    border-radius: 6px;
}
element-text, element-icon {
    background-color: inherit;
    text-color: inherit;
}

element selected {
    background-color: @surface0;
    text-color: @mauve;
}
