cat > "$CONF/rofi/themes/gh0stzk-daniela-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #181825FF;
    mantle:   #1E1E2EFF;
    text:     #CDD6F4FF;
    subtext:  #585B70FF;
    mauve:    #F5C2E7FF;
    surface0: #1E1E2EFF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 16px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @mauve;
    border-radius: 14px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
GH0STZK_EOF
cat > "$CONF/starship/themes/gh0stzk-daniela.toml" <<'GH0STZK_EOF'
format = """
[](#181825)\
$python\
$username\
[](bg:#45475A fg:#181825)\
$directory\
[](fg:#45475A bg:#45475A)\
$git_branch\
$git_status\
[](fg:#45475A bg:#A6E3A1)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#A6E3A1 bg:#F5C2E7)\
$docker_context\
[](fg:#F5C2E7 bg:#89B4FA)\
$time\
[ ](fg:#89B4FA)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#181825"
style_root = "bg:#181825"
format = '[$user ]($style)'

[directory]
style = "bg:#45475A"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#F5C2E7"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#45475A"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#45475A"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#181825"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#A6E3A1"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#89B4FA"
format = '[ $time ]($style)'
GH0STZK_EOF
