cat > "$CONF/starship/themes/gh0stzk-emilia.toml" <<'GH0STZK_EOF'
format = """
[](#1A1B26)\
$python\
$username\
[](bg:#15161E fg:#1A1B26)\
$directory\
[](fg:#15161E bg:#15161E)\
$git_branch\
$git_status\
[](fg:#15161E bg:#9ECE6A)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#9ECE6A bg:#BB9AF7)\
$docker_context\
[](fg:#BB9AF7 bg:#7AA2F7)\
$time\
[ ](fg:#7AA2F7)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#1A1B26"
style_root = "bg:#1A1B26"
format = '[$user ]($style)'

[directory]
style = "bg:#15161E"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#BB9AF7"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#15161E"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#15161E"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#1A1B26"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#9ECE6A"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#7AA2F7"
format = '[ $time ]($style)'
GH0STZK_EOF
