cat > "$CONF/starship/themes/gh0stzk-h4ck3r.toml" <<'GH0STZK_EOF'
format = """
[](#0C1018)\
$python\
$username\
[](bg:#4A9801 fg:#0C1018)\
$directory\
[](fg:#4A9801 bg:#4A9801)\
$git_branch\
$git_status\
[](fg:#4A9801 bg:#00FA5C)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#00FA5C bg:#9CF542)\
$docker_context\
[](fg:#9CF542 bg:#578A29)\
$time\
[ ](fg:#578A29)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#0C1018"
style_root = "bg:#0C1018"
format = '[$user ]($style)'

[directory]
style = "bg:#4A9801"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#9CF542"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#4A9801"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#4A9801"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#0C1018"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#00FA5C"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#578A29"
format = '[ $time ]($style)'
GH0STZK_EOF
