cat > "$CONF/polybar/gh0stzk/rices/isabel/modules.ini" <<'GH0STZK_EOF'
; __  __           _       _
;|  \/  | ___   __| |_   _| | ___  ___
;| |\/| |/ _ \ / _` | | | | |/ _ \/ __|   z0mbi3
