orange = #db330a
brown = #AC8476
grey = #7a8488
indigo = #8f32e4
blue-gray = #1e80d2

[bar/main]
monitor = ${env:MONITOR:}
monitor-strict = false
override-redirect = false

bottom = false
fixed-center = false

width = 100%
height = 40

offset-x = 0
offset-y = 0

background = ${color.bg}
foreground = ${color.fg}

radius = 0

