cat > "$CONF/polybar/gh0stzk/rices/karla/modules.ini" <<'GH0STZK_EOF'
; __  __           _       _
;|  \/  | ___   __| |_   _| | ___  ___
;| |\/| |/ _ \ / _` | | | | |/ _ \/ __|   z0mbi3
;| |  | | (_) | (_| | |_| | |  __/\__ \   https://github.com/gh0stzk/dotfiles
;|_|  |_|\___/ \__,_|\__,_|_|\___||___/   z0mbi3.zk@protonmail.com


[module/date]
type = internal/date

interval = 1.0

time = %I:%M %P
date-alt = "%a, %d %b %Y"

format = <label>
label = "%time%%date%"

######################################################

[module/filesystem]
type = internal/fs

mount-0 = /
interval = 300
fixed-values = true

format-mounted = <label-mounted>
format-mounted-prefix = 
format-mounted-prefix-padding-right = 3pt
label-mounted = %used%

format-unmounted = <label-unmounted>
format-unmounted-prefix = 
format-unmounted-prefix-padding-right = 3pt
label-unmounted = %mountpoint%: not mounted

######################################################

[module/network]
type = internal/network
interface = ${system.sys_network_interface}

interval = 3.0
accumulate-stats = true
unknown-as-up = true

format-connected = <label-connected>
format-connected-prefix = 
format-connected-prefix-padding-right = 3pt
speed-unit = ""
label-connected = "%{A1:OpenApps --netmanager:}%netspeed%%{A}"

format-disconnected = <label-disconnected>
format-disconnected-prefix = 
format-disconnected-prefix-padding-right = 3pt

label-disconnected = "%{A1:OpenApps --netmanager:}Offline%{A}"
label-disconnected-foreground = ${color.red}

######################################################

[module/brightness]
type = internal/backlight
card = ${system.sys_graphics_card}

enable-scroll = false

format = <ramp><label>
label = "%percentage%%"

ramp-0 = 
ramp-1 = 
ramp-2 = 
ramp-font = 2
ramp-padding-right = 3pt
ramp-foreground = ${color.yellow}

######################################################

[module/battery]
type = internal/battery
full-at = 99
battery = ${system.sys_battery}
adapter = ${system.sys_adapter}
poll-interval = 2
time-format = %H:%M

format-charging = <animation-charging><label-charging>
label-charging = "%percentage%% | "

format-discharging = <ramp-capacity><label-discharging>
label-discharging = "%percentage%% | "

format-full = <label-full>
format-full-prefix = 
format-full-prefix-padding-right = 3pt
format-full-prefix-font = 2
label-full = "%percentage%% | "

ramp-capacity-0 = 
ramp-capacity-1 = 
ramp-capacity-2 = 
ramp-capacity-3 = 
ramp-capacity-4 = 
ramp-capacity-padding-right = 3pt
ramp-capacity-font = 2

animation-charging-0 = 
animation-charging-1 = 
animation-charging-2 = 
animation-charging-3 = 
animation-charging-4 = 
animation-charging-padding-right = 3pt
animation-charging-foreground = ${color.green}
animation-charging-font = 2
animation-charging-framerate = 700

######################################################

[module/weather]
type = custom/script
exec = Weather wmodule
interval = 900
format = <label>
label = "%output%"

######################################################

[module/pulseaudio]
type = internal/pulseaudio
use-ui-max = true
interval = 5

format-volume = <label-volume>
format-volume-prefix = ""
format-volume-prefix-padding-right = 3pt
label-volume = "%percentage%"
label-volume-foreground = ${color.fg}

format-muted = <label-muted>
format-muted-prefix = ""
format-muted-prefix-padding-right = 3pt
label-muted = "Muted"
label-muted-foreground = ${color.red}

click-right = OpenApps --soundcontrol

######################################################

[module/title]
type = internal/xwindow

format = <label>
label = "%title%"
label-maxlen = 40

label-empty = "Arch Linux"

######################################################

[module/bspwm]
type = internal/bspwm

enable-click = true
enable-scroll = true
reverse-scroll = true
pin-workspaces = true
occupied-scroll = false

ws-icon-0 = 1;󰆍
ws-icon-1 = 2;󰝰
ws-icon-2 = 3;󰇧
ws-icon-3 = 4;󰍩
ws-icon-4 = 5;󰏖
ws-icon-5 = 6;󰊴
ws-icon-6 = 7;󰣇
ws-icon-7 = 8;󱃋
ws-icon-8 = 9;󱃅

ws-icon-default = "♟"


format = <label-state>

label-focused = 󱓇
label-focused-foreground = ${color.fg}

label-occupied = %icon%
label-occupied-foreground= ${color.fg}

label-urgent = %icon%
label-urgent-foreground= ${color.fg}

label-empty = %icon%
label-empty-foreground = ${color.black}

label-separator = "•"
label-separator-padding = 1
label-separator-foreground = ${color.fg}

######################################################

[module/updates]
type = custom/ipc

hook-0 = cat $HOME/.cache/Updates.txt 2>/dev/null
initial = 1

format = <label>
format-prefix = 
format-prefix-padding-right = 3pt

label = %output%

click-left = OpenApps --checkupdates

######################################################

[module/launcher]
type = custom/text

label = 󰣇󰫿󰫰󰫵
label-foreground = ${color.blue-arch}
label-font = 2

click-left = OpenApps --menu
click-right = RiceSelector

######################################################

[module/sep]
type = custom/text
label = "|"
label-padding = 5pt

[module/sep2]
type = custom/text
label = " "

######################################################

[module/cpu]
type = internal/cpu

interval = 0.5

format = <label>
format-prefix = ""
format-prefix-padding-right = 3pt
label = %percentage%%

######################################################

[module/memory]
type = internal/memory
interval = 3

format = <label>
format-prefix = ""
format-prefix-padding-right = 3pt
label = %used%

######################################################

[module/mpd_control]
type            = internal/mpd

interval        = 2
format-online   = <icon-prev><toggle><icon-next>
format-offline  = <label-offline>
format-offline-foreground = ${color.grey}
label-offline   = "󰝛 no Music"
icon-play       = "  "
icon-pause      = "  "
icon-stop       = "  "
icon-prev       = ""
icon-next       = ""

######################################################

[module/mplayer]
type = custom/text
label = ""

click-left = OpenApps --player
click-right = OpenApps --music

[module/usercard]
type = custom/text
label =  ""

click-left = OpenApps --usercard

[module/power]
type = custom/text
label = ""

click-left = OpenApps --powermenu

#####################################################

[module/tray]
type = internal/tray

format = <tray>
format-background = ${color.bg}
tray-background = ${color.bg}
tray-foreground = ${color.fg}
tray-spacing = 5px
tray-padding = 0px
tray-size = 44%

#####################################################

[module/bluetooth]
type = custom/script
exec = bluetooth-polybar.sh
interval = 3

format = <label>
format-font = 2
label = "%output%"
click-left = OpenApps --bluetooth

#####################################################

[module/xkeyboard]
type = internal/xkeyboard

blacklist-0 = num lock
blacklist-1 = scroll lock

format = <label-layout>
format-prefix = " "
format-prefix-font = 3

label-layout = %{A1:OpenApps --keyboard:}%layout%%{A}

#####################################################

[module/colorpicker]
type = custom/text
label = ""
click-left = Colorpicker
GH0STZK_EOF
cat > "$CONF/rofi/themes/gh0stzk-karla.rasi" <<'GH0STZK_EOF'
* {
    base:     #0E1113F7;
    mantle:   #111517FF;
    text:     #AFB1DBFF;
    subtext:  #353C52FF;
    mauve:    #5884D4FF;
    surface0: #111517FF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 30%;
    border-radius: 12px;
    background-color: @base;
}

inputbar {
    padding: 10px;
    background-color: @mantle;
    border-radius: 8px;
    children: [prompt, entry];
}

prompt { text-color: @mauve; padding: 0 8px 0 0; }
entry  { text-color: @text; }

listview {
    lines: 14;
    padding: 8px 0;
}

element {
    padding: 6px 10px;
    border-radius: 6px;
}
element-text, element-icon {
    background-color: inherit;
    text-color: inherit;
}

element selected {
    background-color: @surface0;
    text-color: @mauve;
}
GH0STZK_EOF
cat > "$CONF/rofi/themes/gh0stzk-karla-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #0E1113F7;
    mantle:   #111517FF;
    text:     #AFB1DBFF;
    subtext:  #353C52FF;
    mauve:    #5884D4FF;
    surface0: #111517FF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

window {
    width: 560px;
    background-color: @base;
    border: 2px;
    border-color: @mauve;
    border-radius: 18px;
    padding: 24px;
}

mainbox {
    children: [ listview ];
}

listview {
    columns: 5;
    lines: 1;
    spacing: 10px;
    fixed-columns: true;
    scrollbar: false;
}

element {
    children: [ element-text ];
    padding: 26px;
    border-radius: 16px;
    background-color: @mantle;
}
element normal.normal {
    text-color: @text;
}
element selected {
    background-color: @surface0;
    border: 2px;
    border-color: @mauve;
    border-radius: 14px;
}
element-text {
    font: "JetBrainsMono Nerd Font 26";
    background-color: transparent;
    text-color: inherit;
    /* Nerd Font glyphs' advance width isn't visually symmetric around their
       ink - 0.5 (true center) renders visibly right-of-center, so this is
       nudged left. */
    horizontal-align: 0.32;
    vertical-align: 0.5;
}
GH0STZK_EOF
cat > "$CONF/starship/themes/gh0stzk-karla.toml" <<'GH0STZK_EOF'
format = """
[](#0E1113)\
$python\
$username\
[](bg:#353C52 fg:#0E1113)\
$directory\
[](fg:#353C52 bg:#353C52)\
$git_branch\
$git_status\
[](fg:#353C52 bg:#61B33E)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#61B33E bg:#7A44E3)\
$docker_context\
[](fg:#7A44E3 bg:#5884D4)\
$time\
[ ](fg:#5884D4)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#0E1113"
style_root = "bg:#0E1113"
format = '[$user ]($style)'

[directory]
style = "bg:#353C52"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#7A44E3"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#353C52"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#353C52"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#0E1113"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#61B33E"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#5884D4"
format = '[ $time ]($style)'
GH0STZK_EOF
