cat > "$CONF/starship/themes/gh0stzk-pamela.toml" <<'GH0STZK_EOF'
format = """
[](#1D1F28)\
$python\
$username\
[](bg:#282A36 fg:#1D1F28)\
$directory\
[](fg:#282A36 bg:#282A36)\
$git_branch\
$git_status\
[](fg:#282A36 bg:#5ADECD)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#5ADECD bg:#C574DD)\
$docker_context\
[](fg:#C574DD bg:#8897F4)\
$time\
[ ](fg:#8897F4)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#1D1F28"
style_root = "bg:#1D1F28"
format = '[$user ]($style)'

[directory]
style = "bg:#282A36"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#C574DD"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#282A36"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#282A36"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#1D1F28"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#5ADECD"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#8897F4"
format = '[ $time ]($style)'
GH0STZK_EOF
