cat > "$CONF/rofi/themes/gh0stzk-silvia-powermenu.rasi" <<'GH0STZK_EOF'
* {
    base:     #282828FF;
    mantle:   #2E2E2EFF;
    text:     #FBF1C7FF;
    subtext:  #A89984FF;
    mauve:    #D79921FF;
    surface0: #2E2E2EFF;

    background-color: @base;
    text-color: @text;
    font: "JetBrainsMono Nerd Font 11";
}

