cat > "$CONF/starship/themes/gh0stzk-silvia.toml" <<'GH0STZK_EOF'
format = """
[](#282828)\
$python\
$username\
[](bg:#A89984 fg:#282828)\
$directory\
[](fg:#A89984 bg:#A89984)\
$git_branch\
$git_status\
[](fg:#A89984 bg:#98971A)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#98971A bg:#B16286)\
$docker_context\
[](fg:#B16286 bg:#458588)\
$time\
[ ](fg:#458588)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#282828"
style_root = "bg:#282828"
format = '[$user ]($style)'

[directory]
style = "bg:#A89984"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#B16286"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#A89984"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#A89984"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#282828"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#98971A"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#458588"
format = '[ $time ]($style)'
GH0STZK_EOF
