label-font = 4
label-foreground = ${color.yellow}

######################################################

[module/cpu_bar]
type = internal/cpu

interval = 0.5
format = <label>
format-font = 2
format-prefix = ""

label = "%percentage%% "
label-padding-left = 8pt

######################################################

[module/memory_bar]
type = internal/memory

interval = 3

;; agregar <bar-used> antes de label para agregar barrita chida
format = <label>
format-prefix = "󰄧"
format-font = 2

label = "%used% "
label-padding-left = 8pt
label-foreground = ${color.purple}

######################################################

[module/mpd_control]
type            = internal/mpd
host            = 127.0.0.1
port            = 6600
interval        = 2

format-online   = <icon-prev><toggle><icon-next>
format-offline  = <label-offline>
label-offline = "󰎊 No Music"
label-offline-font = 2

icon-play               = " %{T2} "
icon-pause              = " %{T2} "
icon-stop               = " %{T2} "
icon-prev               = " %{T2} "
icon-next               = " %{T2}"

format-offline-foreground = ${color.grey}
icon-play-foreground    = ${color.fg}
icon-pause-foreground   = ${color.fg}
icon-stop-foreground    = ${color.fg}
icon-prev-foreground    = ${color.fg}
icon-next-foreground    = ${color.fg}
toggle-on-foreground    = ${color.green}
toggle-off-foreground   = ${color.red}

######################################################

[module/spl]
type = custom/text
label = "["
label-padding-right = 3pt
label-font = 2
label-foreground = ${color.blue}

[module/spr]
type = custom/text
label = "]"
label-padding-left = 3pt
label-font = 2
label-foreground = ${color.blue}

[module/mplayer]
type = custom/text
label = " "
label-padding-right = 3pt
label-font = 2
label-foreground = ${color.green}

click-left = OpenApps --player
click-right = OpenApps --music

[module/usercard]
type = custom/text
label =  " "
label-font = 2
label-foreground = ${color.green}

click-left = OpenApps --usercard

[module/power]
type = custom/text
label = " "
label-font = 2
label-foreground = ${color.red}

click-left = OpenApps --powermenu

#####################################################

[module/tray]
type = internal/tray

format = <tray>
format-background = ${color.bg}
tray-background = ${color.bg}
tray-foreground = ${color.fg}
tray-spacing = 5px
tray-padding = 0px
tray-size = 50%

#####################################################

[module/bluetooth]
type = custom/script
exec = bluetooth-polybar.sh
interval = 3

format = <label>
format-font = 2
label = "%output% "
click-left = OpenApps --bluetooth

#####################################################

[module/xkeyboard]
type = internal/xkeyboard

blacklist-0 = num lock
blacklist-1 = scroll lock

format = <label-layout>
format-prefix = "󰌌"
format-prefix-padding-right = 8pt
format-prefix-font = 2

label-layout = "%{A1:OpenApps --keyboard:}%layout%%{A} "
label-layout-foreground = ${color.purple}

#####################################################

[module/colorpicker]
type = custom/text
label = "󰈋"
label-font = 2
label-foreground = ${color.purple}
click-left = Colorpicker
GH0STZK_EOF
