cat > "$CONF/starship/themes/gh0stzk-varinka.toml" <<'GH0STZK_EOF'
format = """
[](#212529)\
$python\
$username\
[](bg:#2C3136 fg:#212529)\
$directory\
[](fg:#2C3136 bg:#2C3136)\
$git_branch\
$git_status\
[](fg:#2C3136 bg:#ADB5BD)\
$c\
$elixir\
$elm\
$golang\
$haskell\
$java\
$julia\
$nodejs\
$nim\
$rust\
[](fg:#ADB5BD bg:#CED4DA)\
$docker_context\
[](fg:#CED4DA bg:#495057)\
$time\
[ ](fg:#495057)\
"""
command_timeout = 5000
# Disable the blank line at the start of the prompt
# add_newline = false

# You can also replace your username with a neat symbol like  to save some space
[username]
show_always = true
style_user = "bg:#212529"
style_root = "bg:#212529"
format = '[$user ]($style)'

[directory]
style = "bg:#2C3136"
format = "[ $path ]($style)"
truncation_length = 3
truncation_symbol = "…/"

# Here is how you can shorten some long paths by text replacement
# similar to mapped_locations in Oh My Posh:
[directory.substitutions]
"Documents" = "󰈙 "
"Downloads" = " "
"Music" = " "
"Pictures" = " "
# Keep in mind that the order matters. For example:
# "Important Documents" = "  "
# will not be replaced, because "Documents" was already substituted before.
# So either put "Important Documents" before "Documents" or use the substituted version:
# "Important  " = "  "

[c]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[docker_context]
symbol = " "
style = "bg:#CED4DA"
format = '[ $symbol $context ]($style)$path'

[elixir]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[elm]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[git_branch]
symbol = ""
style = "bg:#2C3136"
format = '[ $symbol $branch ]($style)'

[git_status]
style = "bg:#2C3136"
format = '[$all_status$ahead_behind ]($style)'

[golang]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[haskell]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[java]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[julia]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[nodejs]
symbol = ""
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[nim]
symbol = " "
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[python]
style = "bg:#212529"
format = '[(\($virtualenv\) )]($style)'

[rust]
symbol = ""
style = "bg:#ADB5BD"
format = '[ $symbol ($version) ]($style)'

[time]
disabled = false
time_format = "%R" # Hour:Minute Format
style = "bg:#495057"
format = '[ $time ]($style)'
GH0STZK_EOF
